<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><div class="col-xl-8"><h2>Nueva venta</h2><?php if(isset($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(!$asignaciones):?><div class="alert alert-warning">No hay asignaciones activas. El administrador debe asignar un vendedor a una campaña activa.</div><?php else:?><form method="get" action="index.php" class="card p-4 mb-3"><input type="hidden" name="c" value="venta"><input type="hidden" name="a" value="crear"><label class="form-label">1. Elegí la campaña</label><select class="form-select" name="campania" onchange="this.form.submit()"><option value="">Seleccionar...</option><?php foreach($asignaciones as $a):?><option value="<?=$a['campania_id']?>" <?=$campaniaSeleccionada==$a['campania_id']?'selected':''?>><?=e($a['campania'])?><?=esAdministrador()?' — '.e($a['vendedor']):''?></option><?php endforeach;?></select></form><?php if($campaniaSeleccionada):?><form method="post" class="card p-4"><input type="hidden" name="campania_id" value="<?=$campaniaSeleccionada?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Vendedor y campaña</label><select class="form-select" name="asignacion_id" required><?php foreach($asignaciones as $a):if($a['campania_id']==$campaniaSeleccionada):?><option value="<?=$a['id']?>"><?=e($a['campania'])?> — <?=e($a['vendedor'])?></option><?php endif;endforeach;?></select></div><div class="col-md-6"><label class="form-label">Producto</label><select class="form-select" name="producto_id" required><option value="">Seleccionar...</option><?php foreach($productos as $p):?><option value="<?=$p['id']?>"><?=e($p['nombre'])?> — $<?=number_format($p['precio'],2,',','.')?> — stock <?=e($p['stock_actual'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Cantidad</label><input class="form-control" type="number" min="1" name="cantidad" required></div><div class="col-md-3"><label class="form-label">Fecha</label><input class="form-control" type="date" name="fecha_venta" value="<?=date('Y-m-d')?>" required></div><div class="col-md-6"><label class="form-label">Cliente</label><input class="form-control" name="cliente" required></div><div class="col-md-6"><label class="form-label">Teléfono del cliente</label><input class="form-control" name="telefono"></div></div><div class="mt-4"><button class="btn btn-primary" name="guardar">Registrar venta</button><a class="btn btn-light" href="index.php?c=venta&a=inicio">Cancelar</a></div></form><?php endif;endif;?></div></main><?php require __DIR__.'/../footer.php';?>
